                    requirement=attachment.requirement,
                    detail="attachment has no bundle-file locator",
                )
            )
            continue
        try:
            resolved = _confined_bundle_path(
                root,
                locator.value,
                label="bundle-file locator",
            )

"""
llm_engines/factory.py

EngineFactory: construct engines and failover profiles from config.

Supports two YAML formats:

1. Single engine (minimal):
       backend: ollama
       model: qwen3:27b
       options:
         keep_alive: 0

2. Multi-engine profile (from Engram's llm_engines.yaml):
       engines:
         qwen27b:
           type: ollama
           model: qwen3:27b
           base_url: http://localhost:11434
           num_gpu: null
           max_context: 32768
         qwen8b:
           type: ollama
           model: qwen3:8b
       profiles:
         default_local:
           engines: [qwen27b, qwen8b]
           allow_cloud_failover: false
           max_attempts: 4
           circuit_breaker_failures: 3
           circuit_breaker_cooldown_s: 30

Config resolution order (matching Engram):
  1. Explicit path argument
  2. ~/.engram/llm_engines.yaml  (user config)
  3. llm_engines/data/llm_engines.yaml  (packaged default)
"""

from __future__ import annotations

import importlib
import logging
import os
import shutil
from pathlib import Path
from typing import Any, cast

import yaml

from llm_engines.contracts import (
    ChatModel,
    EngineConfigError,
)
from llm_engines.router import FailoverEngine, FailoverPolicy

logger = logging.getLogger(__name__)

_PACKAGED_DEFAULT = Path(__file__).parent / "data" / "llm_engines.yaml"
_USER_CONFIG = Path("~/.engram/llm_engines.yaml").expanduser()

# Lazy-import map: backend name → dotted class path
_BACKEND_MAP: dict[str, str] = {
    "ollama": "llm_engines.backends.ollama.OllamaEngine",
    "anthropic": "llm_engines.backends.anthropic.AnthropicEngine",
    "openai": "llm_engines.backends.openai.OpenAIEngine",
    "vllm": "llm_engines.backends.vllm.vLLMEngine",
    "llamacpp": "llm_engines.backends.llamacpp.LlamaCppEngine",
    "llama_cpp": "llm_engines.backends.llamacpp.LlamaCppEngine",
    "mock": "llm_engines.backends.mock.MockEngine",
}


# ---------------------------------------------------------------------------
# Helpers
# ---------------------------------------------------------------------------


def _import_class(dotted: str) -> type:
    module_path, class_name = dotted.rsplit(".", 1)
    module = importlib.import_module(module_path)
    return cast(type, getattr(module, class_name))


def _load_config(config_path: str | Path | None = None) -> dict[str, Any]:
    """Load YAML config. Resolution: explicit → user → packaged default."""
    if config_path:
        path = Path(config_path).expanduser()
    elif _USER_CONFIG.exists():
        path = _USER_CONFIG
    elif _PACKAGED_DEFAULT.exists():
        path = _PACKAGED_DEFAULT
    else:
        return {}

    if not path.exists():
        raise EngineConfigError(f"Config file not found: {path}")

    try:
        return yaml.safe_load(path.read_text()) or {}
    except yaml.YAMLError as e:
        raise EngineConfigError(f"Invalid YAML in {path}: {e}") from e


def _ensure_user_config() -> Path:
    """Copy packaged default to ~/.engram/ if no user config exists."""
    if not _USER_CONFIG.exists() and _PACKAGED_DEFAULT.exists():
        _USER_CONFIG.parent.mkdir(parents=True, exist_ok=True)
        shutil.copyfile(_PACKAGED_DEFAULT, _USER_CONFIG)
    return _USER_CONFIG


# ---------------------------------------------------------------------------
# Single-engine construction
# ---------------------------------------------------------------------------


def _engine_from_config_dict(
    engine_cfg: dict[str, Any],
    engine_name: str = "<inline>",
) -> ChatModel:
    """
    Build one engine from a config dict.

    Accepts both flat format (backend/model keys) and named-engine format
    (type/model keys, matching Engram's llm_engines.yaml).
    """
    # Normalise key names
    backend = engine_cfg.get("type") or engine_cfg.get("backend")
    if not backend:
        raise EngineConfigError(f"Engine '{engine_name}' must specify 'type' (or 'backend').")
    backend = backend.lower()

    if backend not in _BACKEND_MAP:
        raise EngineConfigError(
            f"Unknown backend '{backend}' in engine '{engine_name}'. "
            f"Available: {sorted(_BACKEND_MAP)}"
        )

    try:
        engine_cls = _import_class(_BACKEND_MAP[backend])
    except ImportError as e:
        raise EngineConfigError(
            f"Backend '{backend}' is not installed. "
            f"Install with: pip install llm-engines[{backend}]"
        ) from e

    # Build kwargs from config, passing only what the constructor accepts
    kwargs: dict[str, Any] = {}

    model = engine_cfg.get("model")
    if model:
        kwargs["model"] = model

    # Ollama-specific
    if backend == "ollama":
        if "base_url" in engine_cfg:
            kwargs["host"] = engine_cfg["base_url"].rstrip("/v1").rstrip("/")
        if "num_gpu" in engine_cfg and engine_cfg["num_gpu"] is not None:
            kwargs["num_gpu"] = int(engine_cfg["num_gpu"])
        if "thinking" in engine_cfg:
            kwargs["think"] = bool(engine_cfg["thinking"])
        if "keep_alive" in engine_cfg:
            kwargs["keep_alive"] = int(engine_cfg["keep_alive"])
        if bool(engine_cfg.get("auto_pull", False)):
            kwargs["auto_pull"] = True

    # Cloud engines
    if backend in ("anthropic", "openai"):
        api_key_env = engine_cfg.get("api_key_env")
        if api_key_env:
            kwargs["api_key"] = os.getenv(api_key_env)
        elif "api_key" in engine_cfg:
            kwargs["api_key"] = engine_cfg["api_key"]
        if "base_url" in engine_cfg:
            kwargs["base_url"] = engine_cfg["base_url"]
        if "is_cloud" in engine_cfg:
            kwargs["is_cloud"] = bool(engine_cfg["is_cloud"])
        if "timeout" in engine_cfg and engine_cfg["timeout"] is not None:
            kwargs["timeout"] = float(engine_cfg["timeout"])
        if "debug" in engine_cfg:
            kwargs["debug"] = bool(engine_cfg["debug"])
        if backend == "openai" and "supports_embeddings" in engine_cfg:
            kwargs["supports_embeddings"] = bool(engine_cfg["supports_embeddings"])

    # vLLM HTTP server
    if backend == "vllm":
        if "base_url" in engine_cfg:
            kwargs["base_url"] = str(engine_cfg["base_url"])
        if "max_context" in engine_cfg and engine_cfg["max_context"] is not None:
            kwargs["max_context"] = int(engine_cfg["max_context"])
        if "timeout" in engine_cfg and engine_cfg["timeout"] is not None:
            kwargs["timeout"] = float(engine_cfg["timeout"])
        if "debug" in engine_cfg:
            kwargs["debug"] = bool(engine_cfg["debug"])

    # llama.cpp (in-process via llama-cpp-python)
    if backend in ("llamacpp", "llama_cpp"):
        # Generic "model" arg maps to LlamaCppEngine's model_path. Accept
        # "gguf_path" as a config-file alias for the same thing.
        if "model" in kwargs:
            kwargs["model_path"] = kwargs.pop("model")
        if "gguf_path" in engine_cfg:
            kwargs["model_path"] = engine_cfg["gguf_path"]
        # base_url doesn't apply to in-process llama.cpp; drop silently if set.
        kwargs.pop("base_url", None)
        # Pass through LlamaCppEngine.__init__ kwargs, coercing types so YAML
        # string values work the same as Python ints/bools.
        for kw in ("n_gpu_layers", "n_ctx", "n_threads", "n_batch", "n_ubatch"):
            if kw in engine_cfg and engine_cfg[kw] is not None:
                kwargs[kw] = int(engine_cfg[kw])
        for kw in ("cache_type_k", "cache_type_v"):
            if kw in engine_cfg and engine_cfg[kw] is not None:
                kwargs[kw] = str(engine_cfg[kw])
        if "thinking" in engine_cfg:
            kwargs["think"] = bool(engine_cfg["thinking"])
        if "think" in engine_cfg:
            kwargs["think"] = bool(engine_cfg["think"])
        for kw in ("flash_attn", "verbose", "embedding"):
            if kw in engine_cfg:
                kwargs[kw] = bool(engine_cfg[kw])

    # Pass-through options
    options = engine_cfg.get("options", {})
    if options:
        kwargs["options"] = options

    try:
        return cast(ChatModel, engine_cls(**kwargs))
    except TypeError as e:
        raise EngineConfigError(
            f"Invalid arguments for backend '{backend}' in engine '{engine_name}': {e}"
        ) from e


# ---------------------------------------------------------------------------
# EngineFactory
# ---------------------------------------------------------------------------


class EngineFactory:
    """
    Create engine instances from config.

    Three usage patterns:

    1. Programmatic single engine:
           engine = EngineFactory.create("ollama", model="qwen3:8b")

    2. From simple YAML file:
           engine = EngineFactory.from_config("myconfig.yaml")

    3. From Engram-format YAML profile:
           engine = EngineFactory.from_profile("default_local", "llm_engines.yaml")
    """

    @classmethod
    def _import_backend(cls, backend: str) -> type:
        """Import and return the engine class for a backend name."""
        backend = backend.lower()
        if backend not in _BACKEND_MAP:
            raise EngineConfigError(
                f"Unknown backend '{backend}'. Available: {sorted(_BACKEND_MAP)}"
            )
        return _import_class(_BACKEND_MAP[backend])

    @classmethod
    def create(cls, backend: str, **kwargs: Any) -> ChatModel:
        """
        Instantiate a single engine by backend name.

        Args:
            backend: "ollama" | "anthropic" | "openai" | "vllm" |
                     "llamacpp" | "mock"
            **kwargs: Passed to the engine constructor.

        Raises:
            EngineConfigError
        """
        cfg = {"type": backend, **kwargs}
        return _engine_from_config_dict(cfg, backend)

    @classmethod
    def from_config(cls, config_path: str | Path) -> ChatModel:
        """
        Build a single engine from a simple YAML file.

        YAML format:
            backend: ollama      # or 'type: ollama'
            model: qwen3:8b
            options:
              keep_alive: 0
        """
        config = _load_config(config_path)

        # Simple flat format: has 'backend' or 'type' at top level
        if "backend" in config or "type" in config:
            return _engine_from_config_dict(config, str(config_path))

        raise EngineConfigError(
            f"{config_path}: expected top-level 'backend'/'type' key for single-engine "
            "format, or use from_profile() for multi-engine YAML."
        )

    @classmethod
    def from_profile(
        cls,
        profile_name: str = "default_local",
        config_path: str | Path | None = None,
        override_engines: list[str] | None = None,
        override_allow_cloud: bool | None = None,
    ) -> FailoverEngine:
        """
        Build a FailoverEngine from a named profile in a YAML config.

        Args:
            profile_name:         Key in the 'profiles' section.
            config_path:          Optional explicit path. Falls back to
                                  ~/.engram/llm_engines.yaml, then packaged default.
            override_engines:     Replace the engine list from the profile.
            override_allow_cloud: Override allow_cloud_failover.

        Returns:
            FailoverEngine (implements ChatModel).

        Raises:
            EngineConfigError
        """
        config = _load_config(config_path)

        profiles = config.get("profiles") or {}
        if profile_name not in profiles:
            available = sorted(profiles)
            raise EngineConfigError(f"Profile '{profile_name}' not found. Available: {available}")

        profile = profiles[profile_name] or {}
        engines_cfg = config.get("engines") or {}

        engine_names: list[str] = override_engines or list(profile.get("engines") or [])
        if not engine_names:
            raise EngineConfigError(f"Profile '{profile_name}' must list at least one engine.")

        engines: list[ChatModel] = []
        for name in engine_names:
            if name not in engines_cfg:
                available = sorted(engines_cfg)
                raise EngineConfigError(
                    f"Engine '{name}' (referenced in profile '{profile_name}') "
                    f"not found in 'engines' section. Available: {available}"
                )
            engine = _engine_from_config_dict(engines_cfg[name], name)
            engines.append(engine)
            logger.debug("Loaded engine '%s' for profile '%s'", name, profile_name)

        allow_cloud = (
            override_allow_cloud
            if override_allow_cloud is not None
            else bool(profile.get("allow_cloud_failover", False))
        )
        policy = FailoverPolicy(
            max_attempts=int(profile.get("max_attempts", 4)),
            allow_cloud_failover=allow_cloud,
            cloud_policy=str(profile.get("cloud_policy", "query_plus_summary")),
            circuit_breaker_failures=int(profile.get("circuit_breaker_failures", 3)),
            circuit_breaker_cooldown_s=float(profile.get("circuit_breaker_cooldown_s", 30.0)),
        )
        return FailoverEngine(engines=engines, policy=policy, name=profile_name)

    @classmethod
    def from_engine_name(
        cls,
        engine_name: str,
        config_path: str | Path | None = None,
    ) -> ChatModel:
        """
        Build a single engine by its named entry in the 'engines' section.

        Compatible with Engram's create_engine() calling convention.
        """
        config = _load_config(config_path)
        engines_cfg = config.get("engines") or {}
        if engine_name not in engines_cfg:
            available = sorted(engines_cfg)
            raise EngineConfigError(f"Engine '{engine_name}' not found. Available: {available}")
        return _engine_from_config_dict(engines_cfg[engine_name], engine_name)

    @classmethod
    def register_backend(cls, name: str, dotted_class_path: str) -> None:
        """Register a custom backend for use in create() and YAML configs."""
        _BACKEND_MAP[name.lower()] = dotted_class_path

"""
llm_engines/backends/openai.py

OpenAIEngine: cloud inference via the OpenAI API (or any OpenAI-compatible endpoint).

Protocols: ChatModel, ToolCallingModel, EmbeddingModel, AsyncStreamingModel
is_cloud = True when using api.openai.com; False for local OpenAI-compat servers.

Requires: pip install llm-engines[openai]
API key: OPENAI_API_KEY env var (or api_key= argument).

Note: vLLMEngine (vllm.py) is a separate backend specialised for local vLLM servers.
This engine is for the OpenAI cloud API and third-party OpenAI-compatible APIs
(Together AI, Groq, etc.) where you have an API key.
"""

from __future__ import annotations

import json
import logging
import os
import time
from typing import Any, AsyncIterator

from llm_engines.contracts import (
    BackendUnavailableError,
    ChatMessage,
    ContextLengthExceededError,
    EmbeddingRequest,
    EmbeddingResponse,
    EngineCapabilities,
    EngineConfigError,
    GenerationError,
    GenerationRequest,
    GenerationResponse,
    LogprobResult,
    GenerationStreamEvent,
    RateLimitError,
    ToolCall,
    ToolCallEvent,
    ToolSpec,
    TokenLogprob,
    StreamFinishedEvent,
    TextDeltaEvent,
    UsageStats,
)

try:
    import openai as _openai
except ImportError as _e:
    raise ImportError(
        "OpenAIEngine requires the 'openai' package. Install with: pip install llm-engines[openai]"
    ) from _e

logger = logging.getLogger(__name__)

BACKEND = "openai"

_FINISH_MAP = {
    "stop": "stop",
    "length": "length",
    "tool_calls": "tool_call",
    "content_filter": "content_filter",
}


def _map_finish(raw: str | None) -> str:
    if raw is None:
        return "unknown"
    return _FINISH_MAP.get(raw, "unknown")


def _to_openai_messages(request: GenerationRequest) -> list[dict[str, Any]]:
    msgs: list[dict[str, Any]] = []
    for m in request.messages:
        if m.role == "tool":
            msgs.append(
                {
                    "role": "tool",
                    "tool_call_id": m.tool_call_id or "",
                    "content": m.content or "",
                }
            )
        elif m.role == "assistant" and m.tool_calls:
            tool_calls_payload = [
                {
                    "id": tc.call_id,
                    "type": "function",
                    "function": {
                        "name": tc.name,
                        # OpenAI-compatible APIs require a JSON string here.
                        # str(dict) uses Python single-quoted syntax, which
                        # llama-server correctly rejects when history is
                        # replayed after the first tool call.
                        "arguments": json.dumps(tc.arguments),
                    },
                }
                for tc in m.tool_calls
            ]
            msgs.append(
                {
                    "role": "assistant",
                    "content": m.content,
                    "tool_calls": tool_calls_payload,
                }
            )
        else:
            msgs.append({"role": m.role, "content": m.content or ""})
    return msgs


def _extract_tool_calls(choice: Any) -> list[ToolCall]:
    raw = getattr(choice.message, "tool_calls", None) or []
    calls = []
    for tc in raw:
        try:
            args = json.loads(tc.function.arguments)
        except Exception:
            args = {"raw": tc.function.arguments}
        calls.append(
            ToolCall(
                call_id=tc.id,
                name=tc.function.name,
                arguments=args,
            )
        )
    return calls


def _apply_local_thinking_preference(
    kwargs: dict[str, Any], request: GenerationRequest, *, is_cloud: bool
) -> None:
    if not is_cloud and request.thinking is not None:
        kwargs["extra_body"] = {"chat_template_kwargs": {"enable_thinking": request.thinking}}


def _apply_seed_preference(kwargs: dict[str, Any], request: GenerationRequest) -> None:
    if request.seed is not None:
        kwargs["seed"] = request.seed


def _apply_json_schema(kwargs: dict[str, Any], request: GenerationRequest) -> None:
    """Forward the canonical request schema to OpenAI-compatible servers."""
    if request.json_schema is not None:
        kwargs["response_format"] = {
            "type": "json_schema",
            "json_schema": {
                "name": "llm_engines_response",
                "schema": request.json_schema,
                "strict": True,
            },
        }


class OpenAIEngine:
    """
    LLM engine backed by the OpenAI API or any OpenAI-compatible endpoint.

    Args:
        model:     Model name, e.g. "gpt-4o-mini", "gpt-4o".
        api_key:   API key. Defaults to OPENAI_API_KEY env var.
        base_url:  Override API endpoint for OpenAI-compatible services
                   (e.g. "https://api.groq.com/openai/v1").
                   Set is_cloud=False for local OpenAI-compat servers.
        is_cloud:  True for cloud APIs (triggers cloud policy in FailoverEngine).
                   Set to False when using a local OpenAI-compat server.
        timeout:   Request timeout in seconds.
        debug:     Preserve raw provider payload in responses.
    """

    def __init__(
        self,
        model: str = "gpt-4o-mini",
        api_key: str | None = None,
        base_url: str | None = None,
        is_cloud: bool = True,
        timeout: float = 60.0,
        debug: bool = False,
        supports_embeddings: bool | None = None,
    ) -> None:
        if not isinstance(is_cloud, bool):
            raise TypeError(f"is_cloud={is_cloud!r} type={type(is_cloud).__name__}")
        resolved_key = api_key or os.getenv("OPENAI_API_KEY")
        if is_cloud and not resolved_key:
            raise EngineConfigError(
                "OpenAIEngine requires OPENAI_API_KEY env var or api_key= argument."
            )
        if not resolved_key:
            # Local OpenAI-compatible servers (llama-server, vLLM, etc.) don't need a real key
            resolved_key = "dummy"

        self.model = model
        self.is_cloud = is_cloud
        self.debug = debug
        self._supports_embeddings = (
            is_cloud if supports_embeddings is None else bool(supports_embeddings)
        )

        client_kwargs: dict[str, Any] = {
            "api_key": resolved_key,
            "timeout": timeout,
        }
        if base_url:
            client_kwargs["base_url"] = base_url

        try:
            self._client = _openai.OpenAI(**client_kwargs)
            self._async_client = _openai.AsyncOpenAI(**client_kwargs)
        except Exception as e:
            raise EngineConfigError(f"Failed to create OpenAI client: {e}") from e

    # ------------------------------------------------------------------
    # ChatModel Protocol
    # ------------------------------------------------------------------

    def get_capabilities(self) -> EngineCapabilities:
        return EngineCapabilities(
            chat=True,
            streaming=False,
            async_streaming=True,
            streaming_tool_calls=True,
            tool_calling=True,
            embeddings=self._supports_embeddings,
            structured_output=True,  # via strict response_format.json_schema
            batch_generation=False,
            vision=False,
            usage_reporting=True,
            logprobs=True,
        )

    def generate(self, request: GenerationRequest) -> GenerationResponse:
        if not request.messages:
            raise GenerationError("messages list cannot be empty")

        messages = _to_openai_messages(request)
        kwargs: dict[str, Any] = {
            "model": self.model,
            "messages": messages,
            "max_tokens": request.max_tokens,
            "temperature": request.temperature,
        }
        if request.stop:
            kwargs["stop"] = request.stop
        _apply_local_thinking_preference(kwargs, request, is_cloud=self.is_cloud)
        _apply_seed_preference(kwargs, request)
        _apply_json_schema(kwargs, request)

        t0 = time.perf_counter()
        try:
            raw = self._client.chat.completions.create(**kwargs)
        except _openai.RateLimitError as e:
            raise RateLimitError(f"OpenAI rate limit: {e}") from e
        except _openai.APIConnectionError as e:
            raise BackendUnavailableError(f"OpenAI unreachable: {e}") from e
        except _openai.BadRequestError as e:
            msg = str(e).lower()
            if "context" in msg or "too long" in msg:
                raise ContextLengthExceededError(str(e)) from e
            raise GenerationError(f"OpenAI bad request: {e}") from e
        except Exception as e:
            raise GenerationError(f"OpenAI generation failed: {e}") from e

        latency_ms = (time.perf_counter() - t0) * 1000
        return self._build_response(raw, latency_ms, request=request)

    def _build_response(
        self, raw: Any, latency_ms: float, *, request: GenerationRequest
    ) -> GenerationResponse:
        choice = raw.choices[0]
        content = choice.message.content
        tool_calls = _extract_tool_calls(choice)
        finish_reason = _map_finish(choice.finish_reason)

        u = getattr(raw, "usage", None)
        usage = UsageStats(
            input_tokens=getattr(u, "prompt_tokens", None),
            output_tokens=getattr(u, "completion_tokens", None),
            total_tokens=getattr(u, "total_tokens", None),
            latency_ms=round(latency_ms, 3),
        )

        return GenerationResponse(
            message=ChatMessage(
                role="assistant",
                content=content,
                tool_calls=tool_calls,
            ),
            finish_reason=finish_reason,  # type: ignore[arg-type]
            usage=usage,
            model_name=getattr(raw, "model", self.model),
            backend=BACKEND,
            raw_provider_payload=({"id": raw.id, "model": raw.model} if self.debug else None),
            seed_status="accepted" if request.seed is not None else "not_requested",
        )

    # ------------------------------------------------------------------
    # ToolCallingModel Protocol
    # ------------------------------------------------------------------

    def generate_with_tools(
        self,
        request: GenerationRequest,
        available_tools: list[ToolSpec],
    ) -> GenerationResponse:
        if not request.messages:
            raise GenerationError("messages list cannot be empty")

        messages: Any = _to_openai_messages(request)
        tools_payload: Any = [t.to_openai_schema() for t in available_tools]

        kwargs: dict[str, Any] = {
            "model": self.model,
            "messages": messages,
            "max_tokens": request.max_tokens,
            "temperature": request.temperature,
            "tools": tools_payload,
            "tool_choice": "auto",
        }
        _apply_local_thinking_preference(kwargs, request, is_cloud=self.is_cloud)
        _apply_seed_preference(kwargs, request)

        t0 = time.perf_counter()
        try:
            raw = self._client.chat.completions.create(**kwargs)
        except _openai.RateLimitError as e:
            raise RateLimitError(f"OpenAI rate limit: {e}") from e
        except _openai.APIConnectionError as e:
            raise BackendUnavailableError(f"OpenAI unreachable: {e}") from e
        except Exception as e:
            raise GenerationError(f"OpenAI tool generation failed: {e}") from e

        return self._build_response(raw, (time.perf_counter() - t0) * 1000, request=request)

    # ------------------------------------------------------------------
    # EmbeddingModel Protocol
    # ------------------------------------------------------------------

    def embed(self, request: EmbeddingRequest) -> EmbeddingResponse:
        if not self._supports_embeddings:
            raise GenerationError(
                "Embeddings are disabled for this OpenAI-compatible endpoint. "
                "Set supports_embeddings=True only when the server exposes /v1/embeddings."
            )
        embed_model = request.model or "text-embedding-3-small"
        try:
            raw = self._client.embeddings.create(
                model=embed_model,
                input=request.texts,
            )
        except _openai.RateLimitError as e:
            raise RateLimitError(f"OpenAI rate limit: {e}") from e
        except _openai.APIConnectionError as e:
            raise BackendUnavailableError(f"OpenAI unreachable: {e}") from e
        except Exception as e:
            raise GenerationError(f"OpenAI embed failed: {e}") from e

        vectors = [item.embedding for item in raw.data]
        dims = len(vectors[0]) if vectors else 0
        return EmbeddingResponse(
            vectors=vectors,
            dimensions=dims,
            model_name=embed_model,
            backend=BACKEND,
        )

    # ------------------------------------------------------------------
    # LogprobModel Protocol
    # ------------------------------------------------------------------

    def generate_with_logprobs(
        self,
        request: GenerationRequest,
        top_logprobs: int = 0,
    ) -> LogprobResult:
        """Generate text with per-token log probabilities."""
        if not request.messages:
            raise GenerationError("messages list cannot be empty")

        kwargs: dict[str, Any] = {
            "model": self.model,
            "messages": _to_openai_messages(request),
            "max_tokens": request.max_tokens,
            "temperature": request.temperature,
            "logprobs": True,
            "top_logprobs": max(1, top_logprobs),
        }
        if request.stop:
            kwargs["stop"] = request.stop
        _apply_local_thinking_preference(kwargs, request, is_cloud=self.is_cloud)
        _apply_seed_preference(kwargs, request)

        try:
            raw = self._client.chat.completions.create(**kwargs)
        except _openai.RateLimitError as e:
            raise RateLimitError(f"OpenAI rate limit: {e}") from e
        except _openai.APIConnectionError as e:
            raise BackendUnavailableError(f"OpenAI unreachable: {e}") from e
        except Exception as e:
            raise GenerationError(f"OpenAI logprob generation failed: {e}") from e

        choice = raw.choices[0]
        token_logprobs: list[TokenLogprob] = []
        choice_logprobs = getattr(choice, "logprobs", None)
        for item in getattr(choice_logprobs, "content", None) or []:
            token_logprobs.append(
                TokenLogprob(
                    token=item.token,
                    logprob=item.logprob,
                    bytes=getattr(item, "bytes", None),
                )
            )
        return LogprobResult(
            text=choice.message.content or "",
            token_logprobs=token_logprobs,
        )

    # ------------------------------------------------------------------
    # AsyncStreamingModel Protocol
    # ------------------------------------------------------------------

    async def stream_async(self, request: GenerationRequest) -> AsyncIterator[str]:
        if not request.messages:
            raise GenerationError("messages list cannot be empty")

        messages: Any = _to_openai_messages(request)
        kwargs: dict[str, Any] = {
            "model": self.model,
            "messages": messages,
            "max_tokens": request.max_tokens,
            "temperature": request.temperature,
            "stream": True,
        }
        _apply_local_thinking_preference(kwargs, request, is_cloud=self.is_cloud)
        _apply_seed_preference(kwargs, request)
        _apply_json_schema(kwargs, request)
        try:
            stream: Any = await self._async_client.chat.completions.create(**kwargs)
            async for chunk in stream:
                delta = chunk.choices[0].delta.content if chunk.choices else None
                if delta:
                    yield delta
        except _openai.RateLimitError as e:
            raise RateLimitError(f"OpenAI rate limit: {e}") from e
        except _openai.APIConnectionError as e:
            raise BackendUnavailableError(f"OpenAI unreachable: {e}") from e
        except Exception as e:
            raise GenerationError(f"OpenAI streaming failed: {e}") from e

    async def stream_with_tools_async(
        self,
        request: GenerationRequest,
        available_tools: list[ToolSpec],
    ) -> AsyncIterator[GenerationStreamEvent]:
        """Stream text while withholding tool calls until their JSON is complete."""
        if not request.messages:
            raise GenerationError("messages list cannot be empty")

        kwargs: dict[str, Any] = {
            "model": self.model,
            "messages": _to_openai_messages(request),
            "max_tokens": request.max_tokens,
            "temperature": request.temperature,
            "tools": [tool.to_openai_schema() for tool in available_tools],
            "tool_choice": "auto",
            "stream": True,
        }
        _apply_local_thinking_preference(kwargs, request, is_cloud=self.is_cloud)
        _apply_seed_preference(kwargs, request)

        # OpenAI-compatible servers stream a tool call across multiple deltas.
        # Buffer by provider index and emit only after strict JSON parsing. This
        # prevents incomplete arguments from becoming executable or entering
        # replayed conversation history.
        buffers: dict[int, dict[str, str]] = {}
        emitted: set[int] = set()
        finish_emitted = False

        def completed_calls() -> list[ToolCallEvent]:
            events: list[ToolCallEvent] = []
            for index in sorted(buffers):
                if index in emitted:
                    continue
                item = buffers[index]
                call_id = item["call_id"]
                name = item["name"]
                arguments_text = item["arguments"]
                if not call_id or not name:
                    raise GenerationError(
                        f"Incomplete streamed tool call at index {index}: "
                        "missing call id or function name"
                    )
                try:
                    arguments = json.loads(arguments_text)
                except (TypeError, ValueError) as exc:
                    raise GenerationError(
                        f"Invalid streamed tool arguments at index {index}: {exc}"
                    ) from exc
                if not isinstance(arguments, dict):
                    raise GenerationError(
                        f"Invalid streamed tool arguments at index {index}: expected a JSON object"
                    )
                events.append(
                    ToolCallEvent(
                        tool_call=ToolCall(
                            call_id=call_id,
                            name=name,
                            arguments=arguments,
                        )
                    )
                )
                emitted.add(index)
            return events

        try:
            stream: Any = await self._async_client.chat.completions.create(**kwargs)
            async for chunk in stream:
                if not chunk.choices:
                    continue
                choice = chunk.choices[0]
                delta = choice.delta
                content = getattr(delta, "content", None)
                if content:
                    yield TextDeltaEvent(text=content)

                for raw_call in getattr(delta, "tool_calls", None) or []:
                    index = int(getattr(raw_call, "index", 0) or 0)
                    item = buffers.setdefault(
                        index,
                        {
                            "call_id": "",
                            "name": "",
                            "arguments": "",
                        },
                    )
                    call_id = getattr(raw_call, "id", None)
                    if call_id:
                        item["call_id"] += str(call_id)
                    function = getattr(raw_call, "function", None)
                    if function is not None:
                        name = getattr(function, "name", None)
                        arguments = getattr(function, "arguments", None)
                        if name:
                            item["name"] += str(name)
                        if arguments:
                            item["arguments"] += str(arguments)

                raw_finish = getattr(choice, "finish_reason", None)
                if raw_finish is not None:
                    for event in completed_calls():
                        yield event
                    yield StreamFinishedEvent(finish_reason=_map_finish(raw_finish))
                    finish_emitted = True

            if not finish_emitted:
                for event in completed_calls():
                    yield event
                yield StreamFinishedEvent(finish_reason="unknown")
        except _openai.RateLimitError as e:
            raise RateLimitError(f"OpenAI rate limit: {e}") from e
        except _openai.APIConnectionError as e:
            raise BackendUnavailableError(f"OpenAI unreachable: {e}") from e
        except GenerationError:
            raise
        except Exception as e:
            raise GenerationError(f"OpenAI tool streaming failed: {e}") from e

from __future__ import annotations
import fcntl
import os
import time
import logging
from pathlib import Path
from typing import Optional

logger = logging.getLogger(__name__)


def _pid_is_alive(pid: int) -> bool:
    """Check if a PID is alive using signal 0. Returns False if dead or permission denied."""
    try:
        os.kill(pid, 0)
        return True
    except ProcessLookupError:
        return False
    except PermissionError:
        # Process exists but we can't signal it — treat as alive
        return True


def _read_lock_pid(lock_path: Path) -> Optional[int]:
    """Read PID from lock file. Returns None if missing, empty, or non-numeric."""
    try:
        content = lock_path.read_text().strip()
        if content:
            return int(content)
    except (ValueError, OSError):
        pass
    return None


class WriterLock:
    """Single-writer file lock using flock().

    Handles stale locks: if the lock file contains a PID that is no longer
    alive, the lock is considered stale and is forcibly acquired.
    """

    LOCK_FILE = ".writer.lock"

    def __init__(self, project_dir: Path):
        self.project_dir = Path(project_dir)
        self.lock_path = self.project_dir / self.LOCK_FILE
        self._fd: Optional[int] = None

    def acquire(self, timeout: float = 5.0) -> bool:
        """Acquire write lock.

        Args:
            timeout: Seconds to wait before giving up on a live-process lock.

        Returns:
            True if acquired.

        Raises:
            RuntimeError: If a live process holds the lock after timeout.
        """
        self.project_dir.mkdir(parents=True, exist_ok=True)

        # Check for stale lock before opening
        self._clear_stale_lock()

        self._fd = os.open(str(self.lock_path), os.O_CREAT | os.O_WRONLY, 0o600)
        deadline = time.monotonic() + timeout

        while True:
            try:
                fcntl.flock(self._fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
                # Write our PID
                os.truncate(self._fd, 0)
                os.lseek(self._fd, 0, os.SEEK_SET)
                os.write(self._fd, f"{os.getpid()}\n".encode())
                logger.debug(f"Writer lock acquired: {self.lock_path}")
                return True

            except BlockingIOError:
                # Another process has the flock — check if it's alive
                holder_pid = _read_lock_pid(self.lock_path)

                if holder_pid is not None and not _pid_is_alive(holder_pid):
                    # Stale lock from dead process
                    logger.warning(
                        f"Stale writer lock from dead PID {holder_pid}. Clearing and retrying."
                    )
                    os.close(self._fd)
                    self._fd = None
                    self._force_clear_lock()
                    return self.acquire(timeout=timeout)

                if time.monotonic() > deadline:
                    holder = holder_pid or "unknown"
                    os.close(self._fd)
                    self._fd = None
                    raise RuntimeError(
                        f"Writer lock held by PID {holder} for {self.lock_path}. "
                        "Only one ProjectMemory writer per project is allowed."
                    )

                time.sleep(0.1)

    def release(self):
        """Release write lock."""
        if self._fd is not None:
            try:
                fcntl.flock(self._fd, fcntl.LOCK_UN)
                os.close(self._fd)
            except Exception as e:
                logger.debug(f"Error releasing lock: {e}")
            finally:
                self._fd = None
            logger.debug(f"Writer lock released: {self.lock_path}")

    def _clear_stale_lock(self):
        """Remove lock file if PID inside is dead or file is unreadable."""
        if not self.lock_path.exists():
            return
        pid = _read_lock_pid(self.lock_path)
        if pid is None:
            # Empty or unreadable — treat as stale
            logger.warning(f"Unreadable lock file at {self.lock_path}, clearing.")
            self._force_clear_lock()
        elif not _pid_is_alive(pid):
            logger.warning(f"Stale lock from dead PID {pid} at {self.lock_path}, clearing.")
            self._force_clear_lock()

    def _force_clear_lock(self):
        """Remove lock file unconditionally."""
        try:
            self.lock_path.unlink(missing_ok=True)
        except OSError as e:
            logger.debug(f"Could not remove lock file: {e}")

    def __enter__(self):
        self.acquire()
        return self

    def __exit__(self, *args):
        self.release()

    def __del__(self):
        try:
            self.release()
        except Exception:
            pass

from __future__ import annotations

from dataclasses import dataclass, field
from typing import Any, Callable

from .contracts import ToolCall, ToolResult, ToolSpec
from .interop import describe_tool_runtime, tool_result_to_operation_result


@dataclass
class LocalTool:
    name: str
    description: str
    handler: Callable[..., Any]
    input_schema: dict[str, Any] = field(default_factory=dict)

    def spec(self) -> ToolSpec:
        return ToolSpec(
            name=self.name,
            description=self.description,
            input_schema=dict(self.input_schema),
        )


class LocalToolRuntime:
    def __init__(self, tools: list[LocalTool] | None = None) -> None:
        self._tools = {tool.name: tool for tool in tools or []}

    def describe_component(self):
        return describe_tool_runtime(self)

    def get_capability_descriptor(self):
        return describe_tool_runtime(self)

    def register(self, tool: LocalTool) -> None:
        self._tools[tool.name] = tool

    def list_tools(self) -> list[ToolSpec]:
        return [tool.spec() for tool in self._tools.values()]

    def invoke(self, call: ToolCall) -> ToolResult:
        tool = self._tools.get(call.name)
        if tool is None:
            return ToolResult(
                name=call.name,
                output=f"Unknown tool: {call.name}",
                success=False,
                meta={"error": "unknown_tool"},
            )
        try:
            output = tool.handler(**call.arguments)
        except Exception as exc:
            return ToolResult(
                name=call.name,
                output=str(exc),
                success=False,
                meta={"error": type(exc).__name__},
            )
        if isinstance(output, ToolResult):
            return output
        return ToolResult(name=call.name, output=output, success=True)

    def invoke_interop(self, call: ToolCall):
        result = self.invoke(call)
        op = tool_result_to_operation_result(result, call=call)
        diagnostics = dict(op.diagnostics)
        diagnostics["capability"] = describe_tool_runtime(self)
        return type(op).success(op.value, warnings=op.warnings, diagnostics=diagnostics)

