from __future__ import annotations
import json
import time
import uuid
from pathlib import Path
from typing import Any, Dict, List, Optional
import logging

logger = logging.getLogger(__name__)


class DimensionMismatchError(ValueError):
    """Raised when embedder dimension doesn't match existing ChromaDB collection."""

    pass


class ChromaDBStore:
    """Persistent ChromaDB collection wrapper. One collection per project."""

    def __init__(
        self,
        persist_directory: Path,
        collection_name: str,
        embedding_dimension: int,
    ):
        try:
            import chromadb
            from chromadb.config import Settings
        except ImportError:
            raise ImportError("chromadb not installed: pip install chromadb")

        self.persist_dir = Path(persist_directory)
        self.persist_dir.mkdir(parents=True, exist_ok=True)
        self.dimension = embedding_dimension

        self.client = chromadb.PersistentClient(
            path=str(self.persist_dir),
            settings=Settings(anonymized_telemetry=False),
        )

        # Check for existing collection and validate dimension
        existing = self._get_existing_collection(collection_name)
        if existing is not None:
            stored_dim = existing.metadata.get("dimension")
            if stored_dim is not None and int(stored_dim) != embedding_dimension:
                raise DimensionMismatchError(
                    f"Embedder dimension mismatch for collection '{collection_name}': "
                    f"existing collection uses {stored_dim}-dim vectors, "
                    f"but current embedder produces {embedding_dimension}-dim vectors. "
                    f"Run: engram-migrate <project_dir> to rebuild with new embedder."
                )

        # Use cosine distance (deterministic similarity = 1 - distance).
        # Default L2 makes thresholding harder because magnitudes vary.
        self.collection = self.client.get_or_create_collection(
            name=collection_name,
            metadata={
                "dimension": embedding_dimension,
                "hnsw:space": "cosine",
            },
        )

    def _get_existing_collection(self, name: str):
        """Return existing collection or None if not found."""
        try:
            return self.client.get_collection(name)
        except Exception:
            return None

    def validate_dimension(self, expected_dim: int) -> bool:
        """Check if collection dimension matches expected. Returns True if match."""
        stored_dim = self.collection.metadata.get("dimension")
        if stored_dim is None:
            return True  # New collection, no mismatch
        return int(stored_dim) == expected_dim

    def add(
        self,
        episode_id: str,
        text: str,
        embedding: List[float],
        metadata: Optional[Dict[str, Any]] = None,
    ):
        if len(embedding) != self.dimension:
            raise ValueError(
                f"Embedding dimension mismatch: expected {self.dimension}, got {len(embedding)}"
            )
        safe_meta = self._sanitize_metadata(metadata or {})
        safe_meta["indexed_at"] = time.time()
        self.collection.add(
            ids=[episode_id],
            embeddings=[embedding],
            documents=[text],
            metadatas=[safe_meta],
        )

    def add_batch(
        self,
        episode_ids: List[str],
        texts: List[str],
        embeddings: List[List[float]],
        metadatas: Optional[List[Dict[str, Any]]] = None,
    ):
        safe = [self._sanitize_metadata(m or {}) for m in (metadatas or [{} for _ in episode_ids])]
        for m in safe:
            m["indexed_at"] = time.time()
        self.collection.add(
            ids=episode_ids,
            embeddings=embeddings,
            documents=texts,
            metadatas=safe,
        )

    def query(
        self,
        query_embedding: List[float],
        n: int = 5,
        where: Optional[Dict[str, Any]] = None,
    ) -> Dict[str, Any]:
        count = self.collection.count()
        if count == 0:
            return {"ids": [[]], "distances": [[]], "documents": [[]], "metadatas": [[]]}
        kwargs: dict = dict(
            query_embeddings=[query_embedding],
            n_results=min(n, count),
        )
        if where:
            kwargs["where"] = where
        return self.collection.query(**kwargs)

    def delete(self, episode_id: str):
        self.collection.delete(ids=[episode_id])

    def update_metadata(
        self,
        doc_id: str,
        metadata: Dict[str, Any],
    ) -> None:
        """Merge metadata fields into an existing document."""
        existing = self.collection.get(ids=[doc_id], include=["metadatas"])
        ids = existing.get("ids") or []
        if not ids:
            return
        metadatas = existing.get("metadatas") or []
        current = dict(metadatas[0] or {}) if metadatas else {}
        current.update(metadata)
        self.collection.update(
            ids=[doc_id],
            metadatas=[self._sanitize_metadata(current)],
        )

    def count(self) -> int:
        return self.collection.count()

    def rebuild_from_episodes(
        self,
        episodes: List[Dict[str, Any]],
        embedder,
        batch_size: int = 50,
    ):
        try:
            self.client.delete_collection(self.collection.name)
        except Exception:
            pass
        self.collection = self.client.create_collection(
            name=self.collection.name,
            metadata={
                "dimension": self.dimension,
                "hnsw:space": "cosine",
            },
        )
        for i in range(0, len(episodes), batch_size):
            batch = episodes[i : i + batch_size]
            ids = [ep.get("id") or str(uuid.uuid4()) for ep in batch]
            texts = [ep.get("text", "") for ep in batch]
            metas = [ep.get("metadata", {}) for ep in batch]
            batch_result = embedder.embed_batch(texts)
            self.add_batch(
                episode_ids=ids,
                texts=texts,
                embeddings=batch_result.embeddings,
                metadatas=metas,
            )

    def _sanitize_metadata(self, metadata: Dict[str, Any]) -> Dict[str, Any]:
        safe = {}
        for key, value in metadata.items():
            if value is None:
                continue
            if isinstance(value, (str, int, float, bool)):
                safe[key] = value
            elif isinstance(value, (list, dict)):
                safe[key] = json.dumps(value)
        return safe

"""Trust policy primitives for persistent memory boundaries."""

from __future__ import annotations

from dataclasses import dataclass
from enum import IntEnum
from typing import Any, Mapping


class TrustLevel(IntEnum):
    """Ordered confidence assigned by the application, never inferred by Engram."""

    UNTRUSTED = 0
    LOW = 1
    VERIFIED = 2
    TRUSTED = 3

    @classmethod
    def parse(cls, value: Any, *, default: "TrustLevel | None" = None) -> "TrustLevel":
        fallback = cls.UNTRUSTED if default is None else cls(default)
        if isinstance(value, cls):
            return value
        if isinstance(value, int) and not isinstance(value, bool):
            try:
                return cls(value)
            except ValueError:
                return fallback
        name = str(value or "").strip().upper()
        return cls.__members__.get(name, fallback)


@dataclass(frozen=True)
class TrustDecision:
    action: str
    reasons: tuple[str, ...] = ()

    @property
    def allowed(self) -> bool:
        return self.action == "accept"


@dataclass(frozen=True)
class MemoryTrustPolicy:
    """Explicit ingestion and recall policy.

    Applications assign trust; Engram only validates and enforces it. When a
    policy is configured, missing trust and tenant metadata fail closed.
    """

    tenant_id: str
    min_ingest_trust: TrustLevel = TrustLevel.VERIFIED
    min_recall_trust: TrustLevel = TrustLevel.VERIFIED
    allowed_sources: frozenset[str] = frozenset()
    allowed_writers: frozenset[str] = frozenset()
    tenant_aliases: frozenset[str] = frozenset()
    ingestion_violation: str = "reject"

    def __post_init__(self) -> None:
        if not str(self.tenant_id).strip():
            raise ValueError("tenant_id must be non-empty")
        if self.ingestion_violation not in {"reject", "quarantine"}:
            raise ValueError("ingestion_violation must be 'reject' or 'quarantine'")
        if any(
            not isinstance(alias, str) or not alias.strip() or alias != alias.strip()
            for alias in self.tenant_aliases
        ):
            raise ValueError("tenant_aliases must contain non-empty normalized strings")
        if self.tenant_id in self.tenant_aliases:
            raise ValueError("tenant_aliases must not repeat tenant_id")

    def normalize_metadata(self, metadata: Mapping[str, Any] | None) -> dict[str, Any]:
        normalized = dict(metadata or {})
        normalized["trust"] = TrustLevel.parse(normalized.get("trust")).name.lower()
        for key in ("tenant", "source", "writer"):
            if key in normalized:
                normalized[key] = str(normalized[key]).strip()
        return normalized

    def ingestion_decision(self, metadata: Mapping[str, Any] | None) -> TrustDecision:
        meta = self.normalize_metadata(metadata)
        reasons = self._boundary_reasons(meta, self.min_ingest_trust)
        return TrustDecision(self.ingestion_violation if reasons else "accept", tuple(reasons))

    def recall_decision(self, metadata: Mapping[str, Any] | None) -> TrustDecision:
        meta = self.normalize_metadata(metadata)
        reasons = self._boundary_reasons(meta, self.min_recall_trust)
        if meta.get("quarantined"):
            reasons.append("quarantined")
        return TrustDecision("filter" if reasons else "accept", tuple(reasons))

    def _boundary_reasons(self, meta: Mapping[str, Any], minimum: TrustLevel) -> list[str]:
        reasons: list[str] = []
        authorized_tenants = {self.tenant_id, *self.tenant_aliases}
        if meta.get("tenant") not in authorized_tenants:
            reasons.append("tenant_mismatch")
        if TrustLevel.parse(meta.get("trust")) < minimum:
            reasons.append("trust_below_minimum")
        if self.allowed_sources and meta.get("source") not in self.allowed_sources:
            reasons.append("source_not_allowed")
        if self.allowed_writers and meta.get("writer") not in self.allowed_writers:
            reasons.append("writer_not_allowed")
        return reasons


__all__ = ["MemoryTrustPolicy", "TrustDecision", "TrustLevel"]
